<?php
namespace App\Http\Controllers;use App\Models\{AdmissionCampaign,Program,Document};class AdmissionController extends Controller{public function __invoke(){return view('admission.index',['campaign'=>AdmissionCampaign::where('is_active',true)->latest()->first(),'programs'=>Program::where('is_active',true)->orderBy('sort')->get(),'documents'=>Document::where('is_published',true)->whereIn('category',['Документы','Образование'])->where(fn($q)=>$q->where('title','like','%прием%')->orWhere('title','like','%приём%')->orWhere('title','like','%заявлен%'))->orderBy('sort')->get()]);}}